namespace ghidra.program.database.data.merge;

using static org.junit.Assert;

using org.junit;

using generic.test;
using ghidra.program.database.data;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.program.model.data;
using ghidra.util;

public class EnumMergerTest : AbstractGenericTest {

	private TransientDataTypeManager dataTypeManager;
	private int txId;

	/* @Before */
	public void setUp()
    {
		UniversalIdGenerator.initialize();
		dataTypeManager = new TransientDataTypeManager("test");
		txId = dataTypeManager.startTransaction("Test");
	}

	/* @After */
	public void tearDown() {
		dataTypeManager.endTransaction(txId, false);
		dataTypeManager.close();
	}

	/* @Test */
	public void testSimpleMerge()
    {
		Enum enum1 = new EnumBuilder("A", 8)
				.entry("joe", 5)
				.buildDb();

		Enum enum2 = new EnumBuilder("B", 8)
				.entry("bob", 10)
				.buildDb();

		Enum expected = new EnumBuilder("A", 8)
				.entry("bob", 10)
				.entry("joe", 5)
				.build();

		EnumMerger merger = new EnumMerger(enum1, enum2);
		Enum result = merger.merge();

		assertEnumEquals(expected, result);
	}

	/* @Test */
	public void testSameValueForDifferentNames()
    {
		Enum enum1 = new EnumBuilder("A", 8)
				.entry("joe", 10)
				.buildDb();

		Enum enum2 = new EnumBuilder("B", 8)
				.entry("bob", 10)
				.buildDb();

		Enum expected = new EnumBuilder("A", 8)
				.entry("bob", 10)
				.entry("joe", 10)
				.build();

		EnumMerger merger = new EnumMerger(enum1, enum2);
		Enum result = merger.merge();

		assertEnumEquals(expected, result);
	}

	/* @Test */
	public void testValueCollision()
    {
		Enum enum1 = new EnumBuilder("A", 8)
				.entry("joe", 5)
				.buildDb();

		Enum enum2 = new EnumBuilder("B", 8)
				.entry("joe", 10)
				.buildDb();

		EnumMerger merger = new EnumMerger(enum1, enum2);

		try {
			merger.merge();
			fail("Expected exception due to value conflict");
		}
		catch (DataTypeMergeException e) {
			assertEquals("Enums have different values for name \"joe\". 5 and 10", e.getMessage());
		}
	}

	/* @Test */
	public void testSizeDifference()
    {
		Enum enum1 = new EnumBuilder("A", 4)
				.entry("joe", 5)
				.buildDb();

		Enum enum2 = new EnumBuilder("B", 8)
				.entry("bob", 10)
				.buildDb();

		Enum expected = new EnumBuilder("A", 8)
				.entry("joe", 5)
				.entry("bob", 10)
				.build();

		EnumMerger merger = new EnumMerger(enum1, enum2);
		Enum result = merger.merge();

		assertEnumEquals(expected, result);
	}

	/* @Test */
	public void testSignedDifference()
    {
		Enum enum1 = new EnumBuilder("A", 1)
				.entry("joe", -5)
				.buildDb();

		Enum enum2 = new EnumBuilder("B", 1)
				.entry("bob", 255)
				.buildDb();

		EnumMerger merger = new EnumMerger(enum1, enum2);
		try {
			merger.merge();
			fail("Expected exception due to signedness conflict");
		}
		catch (DataTypeMergeException e) {
			assertEquals(
				"Enum conflict: one enum has negative values: one has large unsigned values",
				e.getMessage());
		}
	}

	/* @Test */
	public void testCommentMerge()
    {
		Enum enum1 = new EnumBuilder("A", 8)
				.entry("aaa", 1, "hey")
				.entry("bbb", 2)
				.entry("ccc", 3, "hey")
				.entry("ddd", 4, "hey")
				.buildDb();

		Enum enum2 = new EnumBuilder("B", 8)
				.entry("aaa", 1, "hey")
				.entry("bbb", 2, "hey")
				.entry("ccc", 3)
				.entry("ddd", 4, "there")
				.buildDb();

		Enum expected = new EnumBuilder("A", 8)
				.entry("aaa", 1, "hey")
				.entry("bbb", 2, "hey")
				.entry("ccc", 3, "hey")
				.entry("ddd", 4, "hey there")
				.build();

		EnumMerger merger = new EnumMerger(enum1, enum2);
		Enum result = merger.merge();

		assertEnumEquals(expected, result);
	}

	private void assertEnumEquals(Enum expected, Enum actual) {
		if (expected.equals(actual)) {
			return;
		}
		string es = expected.toString();
		string @as = actual.toString();
		string msg = "\nExpected: \n%s\nActual: \n%s".formatted(es, @as);
		fail(msg);
	}

	private class EnumBuilder {
		private Enum result;

		public EnumBuilder(string name, int size) {
			result = new EnumDataType(CategoryPath.ROOT, name, size, dataTypeManager);
		}

		public EnumBuilder entry(string name, long value) {
			result.add(name, value);
			return this;
		}

		public EnumBuilder entry(string name, long value, string comment) {
			result.add(name, value, comment);
			return this;
		}

		public Enum build() {
			return result;
		}

		public Enum buildDb() {
			return (Enum) dataTypeManager.resolve(result, null);
		}
	}

}
